{
  "name": "标准帧源",
  "name_en": "Standard Frame Source",
  "manufacturer": "",
  "description": "一个非物理的软件帧源组件，用于按 frameWrangler 的轮询周期发出图像帧，并通过回调机制把帧组事件提供给漂移跟踪等图像处理逻辑。它用于组织和分发相机帧数据，本身不直接代表具体硬件仪器。",
  "description_en": "A non-physical software frame-source component that emits image frames once per frameWrangler polling interval and provides frame-group events to drift-tracking and related image-processing logic via callbacks. It is used to organize and distribute camera frame data and does not itself represent a specific hardware instrument.",
  "actions": [
    {
      "action_name": "auto-tick",
      "description": "触发一次轮询周期的帧发射或更新。",
      "description_en": "Trigger one polling-cycle frame emission or update."
    },
    {
      "action_name": "shape",
      "description": "获取帧尺寸。",
      "description_en": "Get the frame shape."
    },
    {
      "action_name": "auto-connect",
      "description": "连接一个回调函数以接收帧源事件。",
      "description_en": "Connect a callback to receive frame-source events."
    },
    {
      "action_name": "auto-disconnect",
      "description": "断开一个已连接的回调函数。",
      "description_en": "Disconnect a previously connected callback."
    }
  ],
  "tag_hints": [
    "frame source",
    "camera image stream",
    "drift tracking",
    "callback signaling",
    "frame polling",
    "image processing helper"
  ]
}

